import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787052896000}`),a={name:`reference/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_0-3-2-2026-08-18" tabindex="-1">[0.3.2] - 2026-08-18 <a class="header-anchor" href="#_0-3-2-2026-08-18" aria-label="Permalink to “[0.3.2] - 2026-08-18”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The Basic Auth username and password are no longer left in the environment when <code>WG_EASY_URL</code> is unset. <code>loadConfig</code> deleted them only at the very end, behind the early return for a missing URL, so in that state they stayed in <code>process.env</code> for the whole process lifetime — readable in <code>/proc/&lt;pid&gt;/environ</code> and inherited by every child process. The deletion now happens before any branch.</li><li>A malformed <code>WG_EASY_URL</code> is no longer echoed into the log. That branch fires precisely when the variable does not hold a URL, which most often means a credential was pasted into the wrong variable.</li><li><code>http://[::1]:…</code> no longer produces the &quot;plain http to a non-local host&quot; warning. <code>URL.hostname</code> keeps the brackets around an IPv6 literal, so the loopback check never matched that notation.</li></ul><h2 id="_0-3-1-2026-08-18" tabindex="-1">[0.3.1] - 2026-08-18 <a class="header-anchor" href="#_0-3-1-2026-08-18" aria-label="Permalink to “[0.3.1] - 2026-08-18”">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The architecture diagram no longer depends on the reader&#39;s operating system. It carried a <code>prefers-color-scheme</code> block, which resolves against the OS rather than the theme toggle of GitHub or npm — so dark-mode readers on a light OS got the light artwork on a dark page. The README now uses <code>&lt;picture&gt;</code>, which is resolved against the page, and the <code>&lt;img&gt;</code> that npm falls back to brings its own card instead of a media query.</li><li>The diagram said the server registers ten tools. It registers eleven; the documentation was corrected in a previous release but the drawing was not.</li><li><code>docs/.vitepress/config.ts</code> pointed <code>og:image</code> at <code>/og.png</code>, which did not exist — the documentation site had no link preview at all. The file is generated now.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The diagram is generated from a single source, <code>docs/assets/architecture.source.svg</code>, by <code>npm run assets</code>. The four rendered copies had already drifted apart; CI now fails if one of them is edited by hand.</li><li><code>docs/public/og.png</code> is generated at exactly 1280x640, GitHub&#39;s recommended size for a social preview, instead of being drawn by hand.</li><li>The TypeScript major is now parked in <code>.github/dependabot.yml</code> with its reason, instead of living only as an <code>@dependabot ignore</code> on the closed PR #5 — that state is invisible to anyone reading the config and is lost if the PR is reopened.</li></ul><h2 id="_0-3-0-2026-08-16" tabindex="-1">[0.3.0] - 2026-08-16 <a class="header-anchor" href="#_0-3-0-2026-08-16" aria-label="Permalink to “[0.3.0] - 2026-08-16”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>Dockerfile</code> (multi-stage, non-root, stdio entrypoint) and <code>.dockerignore</code>, so registries that build and introspect the server in a container no longer have to guess a build.</li><li>Multi-arch container images (<code>linux/amd64</code>, <code>linux/arm64</code>) published to <code>ghcr.io/ni-c/wg-easy-mcp</code> with an SBOM and build provenance. <code>server.json</code> now lists the OCI package alongside the npm one.</li><li>Documentation site at <a href="https://wg-easy-mcp.ni-c.de" target="_blank" rel="noreferrer">wg-easy-mcp.ni-c.de</a>: guide, per-tool reference, environment variables and changelog.</li><li>CI additions: CodeQL, a Trivy scan of the image on both architectures, and the GHCR publish job. <code>main</code> now requires all of them.</li><li><code>CONTRIBUTING.md</code>, issue forms and GitHub Discussions.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Missing <code>WG_EASY_URL</code>/<code>WG_EASY_USERNAME</code>/<code>WG_EASY_PASSWORD</code> no longer exit at startup. The server completes the MCP handshake and lists its tools without credentials; they are required when a tool actually calls the API, which then fails with the same setup instructions as before. URL validation still exits, since a bad URL can leak the credentials.</li><li>Payloads returned by the wg-easy API now carry an explicit untrusted-data marker and are capped at 60 000 characters, with the truncation notice naming the call that fetches the rest. Client names, DNS entries and endpoints are free-form strings, so they are marked as data rather than instructions. Server-composed messages, including the delete confirmation, stay unmarked.</li><li>The runtime image no longer contains npm. The entrypoint is plain <code>node</code>, and npm&#39;s vendored dependency tree was the sole source of the container scan&#39;s HIGH/CRITICAL findings.</li><li><code>typescript</code> 6.0.3, <code>typescript-eslint</code> 8.67.0.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h3><ul><li><code>WG_EASY_URL</code> containing embedded credentials (<code>user:password@host</code>) is now rejected at startup. They bypassed the environment wipe in <code>loadConfig</code>, were prefixed onto every request path and were echoed verbatim in the startup log.</li></ul><h2 id="_0-2-2-2026-08-11" tabindex="-1">[0.2.2] - 2026-08-11 <a class="header-anchor" href="#_0-2-2-2026-08-11" aria-label="Permalink to “[0.2.2] - 2026-08-11”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li>Listed in the official <a href="https://registry.modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP Registry</a> as <code>io.github.ni-c/wg-easy-mcp</code>; the release workflow publishes registry updates automatically via GitHub OIDC (<code>server.json</code>, <code>mcpName</code> field).</li><li>npm provenance attestations for published packages.</li><li>CodeQL default setup scanning.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The repository is now public.</li><li>Dependency majors: zod 4 (first release including it; vitest 4 and eslint 10 in the dev toolchain).</li></ul><h2 id="_0-2-1-2026-08-11" tabindex="-1">[0.2.1] - 2026-08-11 <a class="header-anchor" href="#_0-2-1-2026-08-11" aria-label="Permalink to “[0.2.1] - 2026-08-11”">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to “Added”">​</a></h3><ul><li>Release workflow: pushing a <code>v*</code> tag runs the test suite, publishes to npm via trusted publishing (OIDC, no token) and creates a GitHub release from the changelog entry.</li><li>CI: weekly scheduled runs, <code>npm audit</code> job (fails on high/critical), coverage reporting with thresholds on the Node 24 run.</li><li>Dependabot updates for npm dependencies (minor/patch grouped) and pinned GitHub Actions.</li><li>Tests for the configuration loader (URL validation, credential cleanup, plain-http warning).</li></ul><h2 id="_0-2-0-2026-08-11" tabindex="-1">[0.2.0] - 2026-08-11 <a class="header-anchor" href="#_0-2-0-2026-08-11" aria-label="Permalink to “[0.2.0] - 2026-08-11”">​</a></h2><p>Security-hardening release based on an internal code audit.</p><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to “Changed”">​</a></h3><ul><li><strong>Breaking:</strong> <code>delete_client</code> now uses a two-step confirmation-token flow (<code>confirmToken</code> parameter) instead of <code>confirm=true</code>. The first call returns a random, short-lived token; only a second call with that token deletes the client. The client name is no longer echoed in tool responses.</li><li><code>WG_EASY_INSECURE_TLS</code> now uses a request-scoped undici dispatcher instead of setting <code>NODE_TLS_REJECT_UNAUTHORIZED=0</code> process-wide.</li><li><code>get_server_info</code> redacts secret fields (<code>privateKey</code>, <code>preSharedKey</code>, <code>password</code>, session/TOTP secrets) from admin API responses.</li><li>Upstream error bodies are truncated to 2000 characters and HTML error pages are omitted from error results.</li><li><code>WG_EASY_URL</code> is validated (http/https only); a warning is printed for plain-http URLs to non-local hosts. README examples switched to <code>https://</code>.</li><li>API requests now have a 15 s timeout and no longer follow redirects.</li><li>Credentials are removed from <code>process.env</code> after loading the configuration.</li><li>Tool descriptions of <code>get_client_config</code>, <code>get_client_qrcode</code> and <code>generate_one_time_link</code> now flag their output as sensitive.</li><li>CI: least-privilege <code>permissions</code>, actions pinned to commit SHAs, Node matrix 22/24. Minimum supported Node.js version raised to 22 (20 is EOL).</li></ul><h2 id="_0-1-0-2026-08-05" tabindex="-1">[0.1.0] - 2026-08-05 <a class="header-anchor" href="#_0-1-0-2026-08-05" aria-label="Permalink to “[0.1.0] - 2026-08-05”">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial release targeting the wg-easy v15 REST API (Basic Authentication).</li><li>Client management tools: <code>list_clients</code>, <code>get_client</code>, <code>create_client</code>, <code>update_client</code> (partial updates via get-merge-post), <code>enable_client</code>, <code>disable_client</code>, <code>delete_client</code> (guarded by a <code>confirm</code> parameter), <code>get_client_config</code>, <code>get_client_qrcode</code>, <code>generate_one_time_link</code>.</li><li><code>get_server_info</code> aggregating <code>/api/information</code>, <code>/api/admin/general</code> and <code>/api/admin/interface</code> with per-section error tolerance.</li><li>Configuration via <code>WG_EASY_URL</code>, <code>WG_EASY_USERNAME</code>, <code>WG_EASY_PASSWORD</code>, optional <code>WG_EASY_INSECURE_TLS</code>.</li></ul>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};